let catalogueReview=null,catalogueSelected=new Set(),catalogueDecisions=new Map(),catalogueQuery='',catalogueStatus='',catalogueOpen=new Set(),catalogueLimits=new Map();
const catalogueStatusNames={new:'New product',update:'Proposed update',unchanged:'Already up to date',possible:'Possible match',ambiguous:'Multiple stock matches',invalid:'Needs correction'};
function catalogueDetails(item){
  const p=item.catalogue?.product;if(!p)return '';
  return `<details class="catalogue-facts mt"><summary>Manufacturer catalogue information</summary><div class="mt">${dl([['Product',p.name],['Manufacturer',p.manufacturer],['Reference',p.reference],['Sold pack',p.packSize===null?'Unknown':[p.packSize,p.packUnit].filter(Boolean).join(' ')],['Packaging',p.packDescription],['Source checked',p.checkedDate]])}<p class="tiny muted">${p.kind==='part'?'Owned quantities count individual pieces.':'Owned quantities count items / containers.'} A sold pack is not an owned quantity.</p>${p.specifications.length?dl(p.specifications.map(s=>[s.name,[s.value,s.unit].filter(Boolean).join(' ')])):''}${p.sourceUrl?`<p class="catalogue-source tiny">Source: ${esc(p.sourceUrl)}</p>`:''}${p.reviewNotes?`<p class="note">${esc(p.reviewNotes)}</p>`:''}<p class="tiny muted">Catalogue facts are source information. Your stock details and personal notes are managed separately.</p></div></details>`;
}
function catalogueImportCard(){return `<section class="panel catalogue-intro mt"><div class="row">${uiTile('box','blue')}<div><h2>Manufacturer catalogues</h2><p class="muted">Give the import kit to your AI with a manufacturer's website, then review the completed JSON here.</p></div></div><div class="actions mt">${btn('Download import kit','catalogue-kit')}${btn('AI instructions','catalogue-instructions')}${btn('Import catalogue…','catalogue-pick','primary')}${catalogueReview?btn('Continue catalogue review','catalogue-resume'):''}</div><p class="tiny muted">English output instructions, classification examples and all supported part and workshop supply types. New entries start at zero owned stock. Text and specifications only; no website scraping or image downloads.</p></section>`;}
function catalogueGroup(row){return row.product?(row.product.kind==='supply'?'Workshop supplies':'Parts')+' · '+(row.product.category||'Unclassified'):'Invalid records';}
function catalogueFiltered(){return catalogueReview.preview.rows.filter(r=>(!catalogueStatus||r.status===catalogueStatus)&&(!catalogueQuery||[r.product?.name,r.product?.manufacturer,r.product?.reference,r.product?.category].join(' ').toLowerCase().includes(catalogueQuery.toLowerCase())));}
function catalogueChoice(r){if(catalogueDecisions.has(r.index))return catalogueDecisions.get(r.index);if(r.status==='new')return {create:true};if(r.status==='update'&&r.matches.length===1)return {targetId:r.matches[0].id};return null;}
function catalogueSelectable(r){return !r.errors.length&&r.status!=='unchanged'&&!!catalogueChoice(r);}
function catalogueGroupRows(){
  const groups=new Map();for(const row of catalogueFiltered()){const key=catalogueGroup(row);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);}
  return [...groups].map(([name,rows])=>{
    const selectable=rows.filter(catalogueSelectable),selected=selectable.filter(r=>catalogueSelected.has(r.index)),limit=catalogueLimits.get(name)||50;
    return `<details class="panel catalogue-group" data-catalogue-group="${esc(name)}" ${catalogueOpen.has(name)||catalogueQuery?'open':''}><summary><input type="checkbox" aria-label="Select ${esc(name)}" data-catalogue-select-group="${esc(name)}" ${selectable.length&&selected.length===selectable.length?'checked':''} ${selectable.length?'':'disabled'}><strong>${esc(name)}</strong><span class="badge">${rows.length}</span><span class="tiny muted">${selected.length} selected</span></summary><div class="catalogue-product-list">${rows.slice(0,limit).map(r=>`<div class="catalogue-product"><input type="checkbox" aria-label="Select ${esc(r.product?.name||'invalid row '+(r.index+1))}" data-catalogue-select="${r.index}" ${catalogueSelected.has(r.index)?'checked':''} ${catalogueSelectable(r)?'':'disabled'}><button type="button" data-action="catalogue-product" data-id="${r.index}"><strong>${esc(r.product?.name||'Invalid product · row '+(r.index+1))}</strong><small>${esc([r.product?.manufacturer,r.product?.reference].filter(Boolean).join(' · '))}</small><span>${badge(catalogueStatusNames[r.status],r.status==='invalid'?'warn':r.status==='new'?'good':'')}${r.warnings.length?badge(r.warnings.length+' notes','warn'):''}${catalogueChoice(r)&&['possible','ambiguous'].includes(r.status)?badge('Match resolved','good'):''}</span></button>${btn('Review','catalogue-product','small',String(r.index))}</div>`).join('')}${rows.length>limit?`<button type="button" class="btn small" data-action="catalogue-more" data-id="${esc(name)}">Show 50 more (${rows.length-limit} remaining)</button>`:''}</div></details>`;
  }).join('')||'<div class="empty"><h2>No matching products</h2><p>Change the search or status filter.</p></div>';
}
function renderCatalogueReview(){
  if(catalogueReview.databaseId!==db.id){catalogueReview=null;catalogueSelected.clear();return renderExchangeDesign();}
  return heading('Review manufacturer catalogue',catalogueReview.name,btn('Back to Import & Export','catalogue-back')+btn('Refresh matches','catalogue-refresh')+btn('Discard review','catalogue-discard','danger'))+
    `<div class="note info">Nothing has been imported yet. New products start at <strong>zero owned quantity</strong>. Updates change manufacturer catalogue information only; local names, stock quantities, fitted parts, photographs, notes and history stay intact. Source accuracy and physical compatibility need your review.</div><div class="toolbar"><label class="search">${icon('search')}<input id="catalogue-search" placeholder="Find products, references or categories…" value="${esc(catalogueQuery)}" aria-label="Search catalogue"></label><select id="catalogue-status" aria-label="Filter product status"><option value="">All statuses</option>${Object.entries(catalogueStatusNames).map(([key,label])=>`<option value="${key}" ${catalogueStatus===key?'selected':''}>${label}</option>`).join('')}</select>${btn('Select all new products','catalogue-select-new')}${btn('Clear selection','catalogue-clear')}</div><div class="catalogue-import-bar"><span id="catalogue-selection-count">${catalogueSelected.size} selected · ${catalogueReview.preview.rows.length} products in file</span>${btn('Review selected import →','catalogue-confirm','primary')}</div><div id="catalogue-groups">${catalogueGroupRows()}</div>`;
}
function refreshCatalogueGroups(){const container=$('#catalogue-groups');if(!container)return;container.innerHTML=catalogueGroupRows();$('#catalogue-selection-count').textContent=catalogueSelected.size+' selected · '+catalogueReview.preview.rows.length+' products in file';}
async function refreshCatalogueMatches(){
  const previousChoices=new Map(catalogueReview.preview.rows.map(row=>[row.index,JSON.stringify(catalogueChoice(row))]));
  const r=await readScreen();acceptSnapshot(r.data);if(catalogueReview.databaseId!==db.id){catalogueReview=null;throw Error('Database changed. Import the catalogue again.');}
  catalogueReview.preview=await api('plan','catalogue.preview',{input:catalogueReview.input});
  for(const row of catalogueReview.preview.rows){const choice=catalogueDecisions.get(row.index);if(choice&&((choice.targetId&&!row.matches.some(m=>m.id===choice.targetId))||(choice.create&&!['new','possible'].includes(row.status))))catalogueDecisions.delete(row.index);if(!catalogueSelectable(row)||previousChoices.get(row.index)!==JSON.stringify(catalogueChoice(row)))catalogueSelected.delete(row.index);}
}
function catalogueProductDialog(index){
  const row=catalogueReview.preview.rows[index],p=row.product;
  if(!p){modal('Invalid product',`<p>${esc(row.errors.join(' '))}</p><p>Correct this row in the JSON file and import the file again. Other valid products can still be selected.</p>`,null);return;}
  const categories=p.kind==='supply'?slotforgeCatalogue.supplies:slotforgeCatalogue.parts,decision=catalogueChoice(row);
  const text=(key,label,max=200)=>`<label class="field">${label}<input name="${key}" maxlength="${max}" value="${esc(p[key]||'')}"></label>`;
  const options=(list,value)=>'<option value="">Choose…</option>'+list.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('');
  modal('Review product · '+p.name,`${row.errors.length?`<div class="note">${row.errors.map(esc).join('<br>')}</div>`:''}${row.warnings.length?`<div class="note info">${row.warnings.map(esc).join('<br>')}</div>`:''}<div class="form-grid">${text('name','Product name')}${text('manufacturer','Manufacturer')}${text('reference','Product reference / SKU')}<label class="field">Destination<select name="kind" id="catalogue-kind"><option value="part" ${p.kind==='part'?'selected':''}>Part</option><option value="supply" ${p.kind==='supply'?'selected':''}>Workshop supply</option></select></label><label class="field">Category<select name="category" id="catalogue-category">${options(Object.keys(categories),p.category)}</select></label><label class="field">Part / item type<select name="partType" id="catalogue-type">${options(Object.hasOwn(categories,p.category)?categories[p.category]:[],p.partType)}</select></label><label class="field">Supply kind<select name="supplyKind">${options(['Tool / equipment','Consumable'],p.supplyKind)}</select></label><label class="field">Pieces / items in sold pack (unknown: blank)<input name="packSize" type="number" min="1" max="1000000" step="1" value="${p.packSize===null?'':esc(p.packSize)}"></label>${text('packUnit','Pack unit',80)}${text('packDescription','Packaging description',500)}${text('sourceUrl','Product source URL',2048)}${text('checkedDate','Source checked (YYYY-MM-DD)',10)}<label class="field wide">Source uncertainty / review notes<textarea name="reviewNotes" maxlength="4000">${esc(p.reviewNotes)}</textarea></label></div><details class="mt"><summary>Specifications (${p.specifications.length})</summary>${dl(p.specifications.map(s=>[s.name,[s.value,s.unit].filter(Boolean).join(' ')]))}<p class="tiny muted">To correct specification values or unsupported source fields, edit the JSON file and import it again.</p></details><section class="mt"><h3>Existing stock matches</h3>${row.matches.length?row.matches.map(m=>{const old=(m.kind==='part'?db.parts:db.supplies).find(v=>v.id===m.id);return `<details class="catalogue-match"><summary>${esc(m.name)} · ${m.quantity} owned${m.location?' · '+esc(m.location):''}${m.archived?' · archived':''}</summary><p class="tiny muted">${esc(m.maker)} · ${esc(m.reference)} · ${esc(m.id)}</p>${old?catalogueDetails(old):''}<p class="tiny muted">The incoming values above will replace this record's catalogue information only.</p></details>`;}).join(''):'<p class="muted">No existing match found.</p>'}<label class="field mt">When selected for import<select name="decision"><option value="">Leave unresolved / do not import</option>${['new','possible','invalid'].includes(row.status)?`<option value="new" ${decision?.create?'selected':''}>Create a new zero-stock entry</option>`:''}${row.matches.map(m=>`<option value="${m.id}" ${decision?.targetId===m.id?'selected':''}>Update catalogue information · ${esc(m.name)} · ${esc(m.reference||m.id.slice(0,8))}</option>`).join('')}</select></label></section><p class="tiny muted">Saving corrections does not import the product. If its identity or classification changes, matching is checked again.</p>`,async values=>{
    const original=catalogueReview.input.products[index],next={...original};
    for(const key of ['name','manufacturer','reference','kind','category','partType','supplyKind','packUnit','packDescription','sourceUrl','checkedDate','reviewNotes'])next[key]=values[key];next.packSize=values.packSize===''?null:Number(values.packSize);
    const identityChanged=['name','manufacturer','reference','kind','category','partType'].some(k=>next[k]!==original[k]);
    catalogueReview.input.products[index]=next;catalogueDecisions.delete(index);catalogueSelected.delete(index);
    await refreshCatalogueMatches();const fresh=catalogueReview.preview.rows[index];
    if(!identityChanged){if(!values.decision)catalogueDecisions.set(index,null);else if(values.decision==='new'&&['new','possible'].includes(fresh.status))catalogueDecisions.set(index,{create:true});else if(fresh.matches.some(m=>m.id===values.decision))catalogueDecisions.set(index,{targetId:values.decision});}
  },'Save review choices');
}
async function pickCatalogueFile(){
  const result=await api('file','catalogue.pick');if(!result)return;
  catalogueReview={...result,databaseId:db.id,active:true};catalogueSelected=new Set();catalogueDecisions=new Map();catalogueQuery='';catalogueStatus='';catalogueOpen=new Set(result.preview.rows.length<=30?result.preview.rows.map(catalogueGroup):[]);catalogueLimits=new Map();page='Import & Export';
}
async function catalogueAction(action,id){
  if(!action.startsWith('catalogue-'))return false;if(!local())return true;
  if(action==='catalogue-kit'){if(await api('file','catalogue.kit'))toast('Import kit saved. Give this JSON file to your AI.');}
  if(action==='catalogue-instructions'){const prompt=await api('file','catalogue.instructions');modal('Instructions for your AI',`<p>Give your AI the downloaded JSON kit and the manufacturer or retailer URLs. For corrections, also attach the existing catalogue. The kit includes English output requirements and classification guidance.</p><textarea class="catalogue-prompt" readonly aria-label="AI instructions">${esc(prompt)}</textarea><p class="tiny muted">Select the text to copy it, or provide the complete kit file directly.</p>`,null);}
  if(action==='catalogue-pick'){
    if(catalogueReview){modal('Replace the current catalogue review?','<p>Choosing another file replaces your current selections and corrections. Cancel the file chooser to keep this review. No stock has changed.</p>',async()=>pickCatalogueFile(),'Choose another file');return true;}
    await pickCatalogueFile();render();
  }
  if(action==='catalogue-resume'&&catalogueReview){catalogueReview.active=true;render();}
  if(action==='catalogue-back'){catalogueReview.active=false;render();}
  if(action==='catalogue-discard')modal('Discard catalogue review?','<p>Discard these selections and corrections? Nothing has been imported.</p>',async()=>{catalogueReview=null;catalogueSelected.clear();},'Discard review');
  if(action==='catalogue-refresh'){await refreshCatalogueMatches();render();toast('Matches refreshed. Check the selected import before confirming.');}
  if(action==='catalogue-product')catalogueProductDialog(Number(id));
  if(action==='catalogue-more'){catalogueLimits.set(id,(catalogueLimits.get(id)||50)+50);catalogueOpen.add(id);refreshCatalogueGroups();}
  if(action==='catalogue-select-new'){for(const r of catalogueReview.preview.rows)if(r.status==='new'&&catalogueSelectable(r))catalogueSelected.add(r.index);refreshCatalogueGroups();}
  if(action==='catalogue-clear'){catalogueSelected.clear();refreshCatalogueGroups();}
  if(action==='catalogue-confirm'){
    const payload={revision:catalogueReview.preview.revision,input:structuredClone(catalogueReview.input),selections:[...catalogueSelected].map(index=>({index,...catalogueChoice(catalogueReview.preview.rows[index])}))};
    const summary=await api('plan','catalogue.selection',payload);
    modal('Confirm catalogue import',`<p><strong>${summary.created} new zero-stock entries</strong> and <strong>${summary.updated} catalogue updates</strong>.</p><div class="note info">No owned quantities will be added or changed. Existing local fields, fitted inventory and history remain intact. Only the selected products are imported.</div><ul class="catalogue-confirm-list">${summary.chosen.map(c=>`<li>${esc(c.product.name)} · ${c.targetId?'Update catalogue information':'New · 0 owned'}${c.product.reviewNotes?' · has source review notes':''}</li>`).join('')}</ul><label class="check-row"><input name="confirmed" type="checkbox" required>I have reviewed the selected products, source information and matches.</label>`,async values=>{const result=await change('catalogue.apply',{...payload,confirmed:!!values.confirmed});catalogueReview=null;catalogueSelected.clear();toast(result.created+' products added with zero owned stock; '+result.updated+' catalogue records updated.');},'Import selected products');
  }
  return true;
}
document.addEventListener('toggle',e=>{const key=e.target.dataset?.catalogueGroup;if(key){if(e.target.open)catalogueOpen.add(key);else catalogueOpen.delete(key);}},true);
document.addEventListener('input',e=>{if(e.target.id==='catalogue-search'){catalogueQuery=e.target.value;refreshCatalogueGroups();}});
document.addEventListener('change',e=>{
  const el=e.target;if(el.id==='catalogue-status'){catalogueStatus=el.value;refreshCatalogueGroups();}
  if(el.dataset.catalogueSelect!==undefined){const i=Number(el.dataset.catalogueSelect);if(el.checked&&catalogueSelectable(catalogueReview.preview.rows[i]))catalogueSelected.add(i);else catalogueSelected.delete(i);refreshCatalogueGroups();}
  if(el.dataset.catalogueSelectGroup){for(const row of catalogueFiltered().filter(r=>catalogueGroup(r)===el.dataset.catalogueSelectGroup&&catalogueSelectable(r))){if(el.checked)catalogueSelected.add(row.index);else catalogueSelected.delete(row.index);}refreshCatalogueGroups();}
  if(['catalogue-kind','catalogue-category'].includes(el.id)){const categories=$('#catalogue-kind').value==='supply'?slotforgeCatalogue.supplies:slotforgeCatalogue.parts;if(el.id==='catalogue-kind')$('#catalogue-category').innerHTML='<option value="">Choose…</option>'+Object.keys(categories).map(k=>`<option>${esc(k)}</option>`).join('');$('#catalogue-type').innerHTML='<option value="">Choose…</option>'+(Object.hasOwn(categories,$('#catalogue-category').value)?categories[$('#catalogue-category').value]:[]).map(k=>`<option>${esc(k)}</option>`).join('');}
});
